 AND NOT ()

WHERE 1=1
 AND (d.drug_name LIKE CONCAT('%',#{keyword},'%') OR r.case_number LIKE CONCAT('%',#{keyword},'%') OR r.real_name LIKE CONCAT('%',#{keyword},'%') OR CAST(t.prescription_id AS CHAR)=#{keyword})
 AND t.transaction_type=#{type}
 AND DATE(t.create_time)=#{date}

mapper.select:
SELECT t.id,t.drug_id AS `drugId`,t.prescription_id AS `prescriptionId`,t.transaction_type AS type,t.quantity,
 t.stock_after AS `stockAfter`,t.reason,t.create_time AS `createTime`,d.drug_name AS `drugName`,r.case_number AS `caseNumber`,r.real_name AS `realName`,e.realname AS `operatorName`
   ORDER BY t.id DESC LIMIT #{offset},#{size}
